import {exchangePreview as preview,watchExchange} from './exchange-client.mjs';
import {readTradePreferences,writeTradePreferences,watchTradePreferences} from './exchange-preferences.mjs';
import {presenceLabel,sameStarCount} from './chat-model.mjs';
import {playerLink} from './player-model.mjs';
import {supabase,currentUser} from './auth-client.mjs';import {safeAvatar} from './trade-model.mjs';
const $=id=>document.getElementById(id),el=(t,s,c)=>{const n=document.createElement(t);if(s!==undefined)n.textContent=s;if(c)n.className=c;return n;};let data,user,page=0,revision=0;const size=20;
function status(s){$('trade-status').textContent=s;}
function showTrader(row){const block=el('article',undefined,'trader-row'),player=el('div',undefined,'trader-player'),avatar=safeAvatar(row.avatar);if(avatar){const image=el('img');image.src=avatar;image.alt='';image.referrerPolicy='no-referrer';player.append(image)}else player.append(el('span','👤','avatar-placeholder'));const text=el('div'),line=el('div',undefined,'exchange-player-name'),link=el('a',row.name,'trader-name-link'),dot=el('span',undefined,'presence-dot '+(row.online===true?'online':row.online===false?'offline':'unknown'));dot.setAttribute('role','img');dot.setAttribute('aria-label',row.online===true?'Online':row.online===false?'Offline':'Status unavailable');link.href=playerLink(row.uid,4,import.meta.url);line.append(link,dot);text.append(line,el('small',presenceLabel(row.online,row.last_seen)));player.append(text);const same=el('span',sameStarCount(row.swaps,data.cards)+' Cards','exchange-same'),possible=el('span',new Set((row.swaps||[]).map(s=>s.receive)).size+' Cards','exchange-possible'),setting=el('span',row.rarity_mode==='Same Rarity'?'Equal Rarity':row.rarity_mode==='Any Rarity'?'All Rarity':row.rarity_mode||'—','exchange-setting'),attempts=el('span',Number.isInteger(row.trades_left_today)?`${row.trades_left_today}/3`:'—','exchange-attempts'),chat=el('button','Chat','btn');same.dataset.label='Same Star';possible.dataset.label='Possible Match';setting.dataset.label='Trade Setting';attempts.dataset.label='Attempts';chat.disabled=!preview&&!user;chat.title=chat.disabled?'Log in to chat':'Open chat';chat.onclick=e=>{e.stopPropagation();window.dispatchEvent(new CustomEvent('card-chat-open',{detail:row}));};block.tabIndex=0;block.setAttribute('aria-label','View matching cards with '+row.name);const open=()=>window.dispatchEvent(new CustomEvent('card-matches-open',{detail:{row,cards:data.cards,preview}}));block.onclick=e=>{if(!e.target.closest('a,button'))open()};block.onkeydown=e=>{if(e.target===block&&['Enter',' '].includes(e.key)){e.preventDefault();open()}};block.append(player,same,possible,setting,attempts,chat);return block}

function filterPayload(){return {p_season:data.season,p_star:Number($('trade-stars').value)||null,p_type:$('exchange-filter-type').value||null,p_mode:$('exchange-filter-mode').value||null,p_initiator:$('exchange-filter-initiator').value||null,p_online:$('exchange-online-only').checked,p_attempts:$('exchange-has-attempts').checked,p_limit:size,p_offset:page*size}}
async function load(){if(!data)return;const token=++revision;$('trader-list').setAttribute('aria-busy','true');status('Finding traders…');try{user=await currentUser();const payload=filterPayload();let rows;if(preview){rows=[{id:'sample-1',uid:'12345678',name:'Sample collector',online:true,rarity_mode:'Same Rarity',trades_left_today:3,ft:[92,93],swaps:[{give:83,receive:92},{give:84,receive:93}]},{id:'sample-2',uid:'87654321',name:'Sample trader',online:false,last_seen:new Date(Date.now()-42*60000).toISOString(),rarity_mode:'Any Rarity',trades_left_today:1,ft:[59,60],swaps:[{give:55,receive:59},{give:56,receive:60}]}];const matchesCard=n=>{const c=data.cards.find(c=>c.number===n);return c&&(!payload.p_star||c.stars===payload.p_star)&&(!payload.p_type||c.gold===(payload.p_type==='gold'))};rows=rows.filter(r=>(!payload.p_online||r.online)&&(!payload.p_attempts||r.trades_left_today>0)&&(!payload.p_mode||r.rarity_mode===payload.p_mode)&&(!payload.p_initiator||(payload.p_initiator==='me'?Number($('exchange-your-attempts').value)>0:r.trades_left_today>0))).map(r=>({...r,ft:r.ft.filter(matchesCard),swaps:r.swaps.filter(s=>matchesCard(s.receive))})).filter(r=>r.ft.length)}else{const response=await supabase.rpc('exchange_listings',payload);if(response.error)throw response.error;rows=response.data}if(token!==revision)return;$('trader-list').replaceChildren(...rows.map(showTrader));status(rows.length?'':page?'No more players match these filters.':'No players match these filters.');$('previous-page').disabled=page===0;$('next-page').disabled=rows.length<size;$('page-label').textContent='Page '+(page+1)}catch(error){if(token!==revision)return;$('trader-list').replaceChildren();status(error.code==='PGRST202'?'Card Exchange database update is required.':'Could not load traders. Please try again.')}finally{if(token===revision)$('trader-list').setAttribute('aria-busy','false')}}

let settingsBusy=false;
async function syncSettings(){if(!data||settingsBusy)return;const mode=$('exchange-your-mode'),attempts=$('exchange-your-attempts');mode.disabled=attempts.disabled=true;try{const prefs=await readTradePreferences(data.season,preview);mode.querySelector('[data-legacy]')?.remove();if(!['Any Rarity','Same Rarity'].includes(prefs.rarity_mode)){const option=new Option(prefs.rarity_mode+' (current)',prefs.rarity_mode);option.disabled=true;option.dataset.legacy='true';mode.append(option)}mode.value=prefs.rarity_mode;attempts.value=String(prefs.trades_left_today);mode.disabled=attempts.disabled=false;$('exchange-settings-status').textContent=''}catch(e){$('exchange-settings-status').textContent=e.message}}
async function saveSetting(field,value){if(settingsBusy)return;settingsBusy=true;$('exchange-your-mode').disabled=$('exchange-your-attempts').disabled=true;try{await writeTradePreferences(data.season,{[field]:value},preview);$('exchange-settings-status').textContent='Saved.';await load()}catch(e){$('exchange-settings-status').textContent=e.message}finally{settingsBusy=false;await syncSettings()}}
$('exchange-your-mode').onchange=()=>saveSetting('rarity_mode',$('exchange-your-mode').value);$('exchange-your-attempts').onchange=()=>saveSetting('trades_left_today',Number($('exchange-your-attempts').value));watchTradePreferences(async()=>{if(settingsBusy)return;await syncSettings();await load()});
$('refresh-listings').onclick=()=>{page=0;load()};for(const id of ['trade-stars','exchange-filter-mode','exchange-filter-type','exchange-filter-initiator','exchange-online-only','exchange-has-attempts'])$(id).onchange=()=>{page=0;load()};
$('previous-page').onclick=()=>{page=Math.max(0,page-1);load()};$('next-page').onclick=()=>{page++;load()};supabase.auth.onAuthStateChange(()=>{setTimeout(()=>{syncSettings();load()},0)});
try{const r=await fetch(new URL('./album-data/autumn-tales.json',import.meta.url));if(!r.ok)throw Error('Album catalog unavailable');data=await r.json();await syncSettings();await load();}catch(e){status(e.message);}

let visibleTimer=setInterval(()=>{if(!document.hidden&&!settingsBusy)load()},60000);window.addEventListener('pagehide',()=>clearInterval(visibleTimer),{once:true});watchExchange(state=>{if(!preview&&state.actor?.id!==user?.id){user=state.actor;revision++;$('trader-list').replaceChildren();if(data)setTimeout(load,0)}});
